import json,re
from datetime import datetime
rows=[json.loads(l) for l in open('commits.jsonl') if l.strip()]
# build revert target set
targets=set()
for r in rows:
    for l in r['message'].splitlines():
        m=re.match(r'This reverts commit ([0-9a-f]+)\.?$', l)
        if m: targets.add(m.group(1))
print('targets',targets)
header_re=re.compile(r'^([a-z]+)(?:\(([^\s()]+)\))?(!)?: (.+)$')
included=[]
ignored=[]
for r in rows:
    h=r['message'].split('\n')[0]
    m=header_re.match(h)
    if not m:
        ignored.append((r,'noheader')); continue
    typ,scope,bang,summary=m.groups()
    breaking=bool(bang)
    if h.startswith('Revert "'):
        ignored.append((r,'revert')); continue
    if r['hash'] in targets:
        ignored.append((r,'reverted')); continue
    scope=scope or 'general'
    if scope=='deps': scope='dependencies'
    if scope=='internal' and not breaking:
        ignored.append((r,'internal')); continue
    if not breaking and typ not in ('feat','fix','perf'):
        ignored.append((r,'type')); continue
    section='Breaking changes' if breaking else {'feat':'Features','fix':'Fixes','perf':'Features'}[typ]
    # summary formatting
    s=summary
    if s:
        s=s[0].upper()+s[1:]
    if s.endswith('.'):
        s=s[:-1]
    if typ=='perf' and not breaking:
        s=s+' [perf]'
    # issue refs
    issues=[]
    if typ=='fix':
        for l in r['message'].split('\n')[1:]:
            mm=re.match(r'Fixes #(\d+)$',l)
            if mm: issues.append(mm.group(1))
    included.append(dict(r=r,typ=typ,scope=scope,breaking=breaking,section=section,summary=s,issues=issues,dt=datetime.fromisoformat(r['date'])))
print('included',len(included),'ignored',len(ignored))
from collections import Counter
print(Counter(x['section'] for x in included))
print(Counter(x[1] for x in ignored))
print('\nIGNORED details:')
for r,why in ignored:
    print(why, r['hash'][:7], repr(r['message'].split('\n')[0]))
print('\nINCLUDED:')
for x in sorted(included,key=lambda x:(x['section'],x['scope'],-x['dt'].timestamp())):
    print(x['section'],'|',x['scope'],'|',x['summary'],'|',x['issues'],'|',x['r']['hash'][:7],'|',x['dt'].isoformat())
PY","description":"Draft parse and list included commits"}

