import json,re
from datetime import datetime
from collections import defaultdict,Counter
# mailmap
mailmap={}
for line in open('.mailmap',encoding='utf-8'):
    line=line.strip()
    if not line or line.startswith('#'): continue
    m=re.match(r'^(.*?)\s*<([^<>]+)>\s+<([^<>]+)>$',line)
    if m:
        name,proper_email,commit_email=m.groups(); name=name.strip()
        if name: mailmap[commit_email.strip()]=name
        continue
    m=re.match(r'^(.*?)\s*<([^<>]+)>$',line)
    if m:
        name,email=m.groups(); name=name.strip()
        if name: mailmap[email.strip()]=name
def canon(name,email): return mailmap.get(email,name)
rows=[json.loads(l) for l in open('commits.jsonl') if l.strip()]
targets=set()
for r in rows:
    for l in r['message'].splitlines():
        m=re.match(r'This reverts commit ([0-9a-f]+)\.?$',l)
        if m: targets.add(m.group(1))
header_re=re.compile(r'^([a-z]+)(?:\(([^\s()]+)\))?(!)?: (.+)$')
inc=[]
for r in rows:
    h=r['message'].split('\n')[0]; m=header_re.match(h)
    if not m: continue
    typ,scope,bang,summary=m.groups(); breaking=bool(bang)
    if h.startswith('Revert "') or r['hash'] in targets: continue
    scope=scope or 'general'
    if scope=='deps': scope='dependencies'
    if scope=='internal' and not breaking: continue
    if not breaking and typ not in ('feat','fix','perf'): continue
    inc.append(r)
authored=Counter(); co=Counter(); credits=defaultdict(list)
for r in inc:
    a=canon(r['author'],r['email'])
    people=[]
    if not a.endswith('[bot]'): people.append(a); authored[a]+=1
    for l in r['message'].splitlines():
        m=re.match(r'^Co-authored-by:\s*(.+?)\s*<([^<>]+)>$',l)
        if m:
            n=canon(m.group(1),m.group(2))
            if not n.endswith('[bot]') and n not in people: people.append(n)
    for p in people:
