    line=line.strip()
    if not line or line.startswith('#'): continue
    m=re.match(r'^(.*?)\s*<([^<>]+)>\s+<([^<>]+)>$',line)
    if m:
        name,pe,ce=m.groups(); name=name.strip()
        if name: mailmap[ce.strip()]=name
def canon(n,e): return mailmap.get(e,n)
